/**
 * v3.54.14 R2 — the automatic coloured sketch of one elevation: the provider's API reads the ORIGINAL elevation into
 * typed contours (the building's silhouette, roof planes, wall finish zones, openings, elements, the ground line) in
 * that picture's own pixels; a local deterministic renderer draws them in a fixed flat palette at the frame's exact size.
 * JSON → deterministic drawing: no raster is edited or generated by a model.
 *
 * Before a sketch is used its proportions are checked against what does not come from it: the elevation's registration
 * (the building's ends and the ground row the solver fitted on the original), the section's ridge, the model's openings
 * on that side. Residuals are written with their tolerance (a pixel-and-uncertainty bound, never a fixed share); a sketch
 * whose anchors miss is REJECTED (it is not stretched to fit), a region that misses is dropped.
 *
 * Used two ways (L-MS): the rendered raster stands in for the original elevation in the shape reader (an explicit
 * option, `elevationSketches`), and its wall zones become an appearance observation for the finish consumer.
 */
import { createHash } from 'node:crypto'
import { z } from 'zod'
import type { Raster } from '@buildapp/source-cv'
import { encodePng } from '../diagnostics.js'
import { fillPolygon, grid } from './mask.js'
import { APPEARANCE_OBSERVATION_SCHEMA, APPEARANCE_OBSERVATION_VERSION } from './contract.js'
import type { AppearanceObservation } from './contract.js'
import { ConsultantUnavailable } from '../consult/loop.js'
import type { ConsultSpend, ConsultantModel, ModelTurn, Price } from '../consult/loop.js'

export const ELEVATION_SKETCH_SCHEMA = 'buildapp.elevation-sketch' as const
export const ELEVATION_SKETCH_VERSION = '1.0.0' as const
export const ELEVATION_SKETCH_PROMPT_VERSION = 'elevation-sketch/1' as const
/** 2: a roof given as a bare polygon is read as one (recorded); the eaves are tested on roof contours only. */
export const ELEVATION_SKETCH_PARSER_VERSION = 2 as const
export const SKETCH_RENDERER_VERSION = '1.0.0' as const

const finite = z.number().finite()
const Pt = z.tuple([finite, finite])
const Poly = z.array(Pt).min(3)
const WALL_CLASSES = ['LIGHT_RENDER', 'DARK_RENDER', 'TIMBER', 'BRICK', 'METAL', 'UNKNOWN'] as const
const OPENING_KINDS = ['WINDOW', 'DOOR', 'GLAZED_DOOR', 'GATE', 'GLAZED_WALL'] as const
const ELEMENT_KINDS = ['BALCONY', 'RAILING', 'CHIMNEY', 'CANOPY', 'POST', 'PERGOLA', 'FRAME', 'BAND', 'PLINTH', 'TERRACE', 'STEPS', 'GUTTER_DOWNPIPE', 'SOLAR_PANELS', 'OTHER'] as const
const VIS = ['VISIBLE', 'PARTLY_OCCLUDED', 'INFERRED', 'UNKNOWN'] as const

export const ElevationSketchSchema = z
  .object({
    schema: z.literal(ELEVATION_SKETCH_SCHEMA),
    schemaVersion: z.literal(ELEVATION_SKETCH_VERSION),
    sketchId: z.string(),
    frameId: z.string(),
    source: z.object({ imageSha256: z.string().regex(/^[0-9a-f]{64}$/), width: z.number().int().positive(), height: z.number().int().positive(), scale: z.number().positive() }).strict(),
    /** Frame pixels throughout (x right, y down). */
    groundRow: finite.nullable(),
    silhouette: Poly.nullable(),
    roofs: z.array(z.object({ id: z.string(), polygon: Poly }).strict()),
    walls: z.array(z.object({ id: z.string(), class: z.enum(WALL_CLASSES), polygon: Poly, host: z.string().max(60), visibility: z.enum(VIS) }).strict()),
    openings: z.array(z.object({ id: z.string(), kind: z.enum(OPENING_KINDS), polygon: Poly, host: z.string().max(60) }).strict()),
    elements: z.array(z.object({ id: z.string(), kind: z.enum(ELEMENT_KINDS), polygon: Poly }).strict()),
    producer: z.object({ kind: z.literal('API_CONTOUR_READING'), model: z.string(), promptVersion: z.string() }).strict(),
    refused: z.array(z.string()),
  })
  .strict()
export type ElevationSketch = z.infer<typeof ElevationSketchSchema>

const polyProp = (desc: string) => ({ type: 'array', description: desc, items: { type: 'array', items: { type: 'number' }, minItems: 2, maxItems: 2 }, minItems: 3 })
const TOOL = {
  name: 'report_elevation',
  description: 'Report the elevation as contours in pixels of the picture you were sent.',
  input_schema: {
    type: 'object',
    additionalProperties: false,
    required: ['groundRow', 'silhouette', 'roofs', 'walls', 'openings', 'elements'],
    properties: {
      groundRow: { type: ['number', 'null'], description: 'the pixel row of the ground line / ±0.00 at the building' },
      silhouette: { ...polyProp('the outline of the whole building as seen (walls and roof), clockwise; no trees, no terrain'), type: ['array', 'null'] },
      roofs: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['polygon'], properties: { polygon: polyProp('one roof surface as seen (a slope, a flat roof band)') } } },
      walls: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['class', 'polygon', 'host', 'visibility'], properties: { class: { enum: WALL_CLASSES }, polygon: polyProp('one zone of one wall finish, openings included'), host: { type: 'string', description: 'which body: main, garage, wing, gable, ...' }, visibility: { enum: VIS } } } },
      openings: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['kind', 'polygon', 'host'], properties: { kind: { enum: OPENING_KINDS }, polygon: polyProp('the opening in the wall (its frame outline); a raked glazing by its real corners'), host: { type: 'string' } } } },
      elements: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['kind', 'polygon'], properties: { kind: { enum: ELEMENT_KINDS }, polygon: polyProp('the element as seen') } } },
    },
  },
} as const

export const ELEVATION_SKETCH_SYSTEM = `You turn one architectural elevation of a house into simple typed contours, so a flat-colour sketch can be drawn from them. You do not measure and you do not describe the house.

Give every polygon in pixels of the picture you were sent, by its real corners (a raked glazing keeps its slope; a gable keeps its apex). Keep the drawing's proportions exactly: never widen, straighten or tidy a part.
- silhouette: the building's outline (walls and roof) — not trees, not the terrain, not the plot.
- roofs: each roof surface you see (a slope, a flat roof's edge band).
- walls: the zones of wall finish, by material: LIGHT_RENDER (light plaster), DARK_RENDER (dark plaster/panels), TIMBER (wood cladding), BRICK (facing brick or clinker), METAL; each zone with its openings inside it (do not cut them out). A finish hidden behind something (a railing, a post) is INFERRED there, never VISIBLE.
- openings: every window, door, glazed door, garage gate, glazed wall, by the outline of its frame.
- elements: balconies, railings, chimneys, canopies, posts, pergolas, frames, bands, plinths, terraces, steps, downpipes, solar panels.
- groundRow: the row where the building meets the ground (±0.00).
Leave out what is not part of the building (vegetation, people, cars, sky, shadows, text, dimension lines).`

export type SketchFrame = { frameId: string; raster: Raster; caption: string }
type Ctx = { model: ConsultantModel; price: Price; spend?: ConsultSpend; signal?: AbortSignal }

const sha = (b: Uint8Array | string): string => createHash('sha256').update(b).digest('hex')
const usdOf = (p: Price, i: number, o: number): number => Math.round(((i * p.inputUsdPerMTok + o * p.outputUsdPerMTok) / 1e6) * 1e6) / 1e6
const MAX_SIDE = 1400

function downscaled(r: Raster): { png: Uint8Array; width: number; height: number; scale: number } {
  const k = Math.max(1, Math.ceil(Math.max(r.width, r.height) / MAX_SIDE))
  const w = Math.floor(r.width / k)
  const h = Math.floor(r.height / k)
  const data = new Uint8ClampedArray(w * h * 4)
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const si = (y * k * r.width + x * k) * 4
    const di = (y * w + x) * 4
    data[di] = r.data[si]
    data[di + 1] = r.data[si + 1]
    data[di + 2] = r.data[si + 2]
    data[di + 3] = 255
  }
  return { png: encodePng({ width: w, height: h, data }), width: w, height: h, scale: k }
}

/** Ids by kind and the polygon's centroid cell (24 px of the frame), never the answer order. */
function idOf(prefix: string, poly: ReadonlyArray<readonly [number, number]>, taken: Set<string>): string {
  const cx = poly.reduce((s, p) => s + p[0], 0) / poly.length
  const cy = poly.reduce((s, p) => s + p[1], 0) / poly.length
  const base = `${prefix}-${Math.round(cx / 24)}-${Math.round(cy / 24)}`
  let id = base
  for (let n = 1; taken.has(id); n++) id = `${base}-${n}`
  taken.add(id)
  return id
}

export type SketchRead = { sketch?: ElevationSketch; raw: unknown; usd: number; requestId?: string; failed?: string }

/** One request per elevation: the original picture, the tool, nothing else of the analyzer's. */
export async function readElevationSketch(ctx: Ctx, f: SketchFrame): Promise<SketchRead> {
  const pic = downscaled(f.raster)
  const content = [
    { type: 'text', text: `An elevation of a house — "${f.caption}". The picture is ${pic.width} × ${pic.height} px.` },
    { type: 'image', source: { type: 'base64', media_type: 'image/png', data: Buffer.from(pic.png).toString('base64') } },
  ]
  const reserveUsd = usdOf(ctx.price, Math.ceil((ELEVATION_SKETCH_SYSTEM.length + JSON.stringify(TOOL).length) / 2.5) + 2600, ctx.model.maxOutputTokens)
  const reservation = ctx.spend?.reserve(ctx.model.model, reserveUsd, `elevation sketch ${f.frameId}`)
  let turn: ModelTurn
  try {
    turn = await ctx.model.send({ system: ELEVATION_SKETCH_SYSTEM, messages: [{ role: 'user', content }], tools: [TOOL], ...(ctx.signal ? { signal: ctx.signal } : {}) })
  } catch (e) {
    const reason = e instanceof ConsultantUnavailable ? e.reason : 'TRANSPORT'
    if (reservation) ctx.spend?.settle(reservation, reason === 'NO_CREDENTIALS' || reason === 'REJECTED_UNBILLED' || reason === 'BUDGET' ? 'NOT_SENT' : { usd: reserveUsd, inputTokens: 0, outputTokens: 0 }, reason)
    return { raw: null, usd: 0, failed: `${reason}: ${(e as Error).message.slice(0, 200)}` }
  }
  const it = turn.usage.inputTokens ?? 0
  const ot = turn.usage.outputTokens ?? 0
  const usd = usdOf(ctx.price, it, ot)
  if (reservation) ctx.spend?.settle(reservation, { usd, inputTokens: it, outputTokens: ot })
  const raw = (turn.content as Array<{ type: string; name?: string; input?: unknown }>).find((b) => b.type === 'tool_use' && b.name === TOOL.name)?.input as Record<string, unknown> | undefined
  if (!raw) return { raw: turn.content, usd, failed: 'no report_elevation answer', ...(turn.requestId ? { requestId: turn.requestId } : {}) }
  const refused: string[] = []
  const k = pic.scale
  const inside = (p: number[]): boolean => p[0] >= -4 && p[1] >= -4 && p[0] <= pic.width + 4 && p[1] <= pic.height + 4
  const poly = (v: unknown, what: string): Array<[number, number]> | undefined => {
    const r = Poly.safeParse(v)
    if (!r.success) {
      refused.push(`${what}: not a polygon`)
      return undefined
    }
    if (!r.data.every(inside)) {
      refused.push(`${what}: a corner outside the picture`)
      return undefined
    }
    return r.data.map(([x, y]) => [x * k, y * k] as [number, number])
  }
  const taken = new Set<string>()
  const list = (v: unknown): Array<Record<string, unknown>> => (Array.isArray(v) ? (v as Array<Record<string, unknown>>) : [])
  // a roof given as a bare polygon (the points without the {polygon} object around them) is the same statement; it is
  // read as one and the normalization is recorded
  const roofs = list(raw.roofs).flatMap((r, i) => {
    const bare = Array.isArray(r)
    if (bare) refused.push(`roof ${i}: given as a bare polygon, read as {polygon} (normalized, not refused)`)
    const p = poly(bare ? r : r.polygon, `roof ${i}`)
    return p ? [{ id: idOf('roof', p, taken), polygon: p }] : []
  })
  const walls = list(raw.walls).flatMap((r, i) => {
    const p = poly(r.polygon, `wall ${i}`)
    const cls = WALL_CLASSES.includes(r.class as never) ? (r.class as (typeof WALL_CLASSES)[number]) : undefined
    if (!cls) refused.push(`wall ${i}: class ${String(r.class)}`)
    return p && cls ? [{ id: idOf(`wall-${cls.toLowerCase()}`, p, taken), class: cls, polygon: p, host: String(r.host ?? '').slice(0, 60), visibility: (VIS.includes(r.visibility as never) ? r.visibility : 'UNKNOWN') as (typeof VIS)[number] }] : []
  })
  const openings = list(raw.openings).flatMap((r, i) => {
    const p = poly(r.polygon, `opening ${i}`)
    const kind = OPENING_KINDS.includes(r.kind as never) ? (r.kind as (typeof OPENING_KINDS)[number]) : undefined
    if (!kind) refused.push(`opening ${i}: kind ${String(r.kind)}`)
    return p && kind ? [{ id: idOf(`opening-${kind.toLowerCase()}`, p, taken), kind, polygon: p, host: String(r.host ?? '').slice(0, 60) }] : []
  })
  const elements = list(raw.elements).flatMap((r, i) => {
    const p = poly(r.polygon, `element ${i}`)
    const kind = ELEMENT_KINDS.includes(r.kind as never) ? (r.kind as (typeof ELEMENT_KINDS)[number]) : 'OTHER'
    return p ? [{ id: idOf(`element-${kind.toLowerCase()}`, p, taken), kind, polygon: p }] : []
  })
  const silhouette = raw.silhouette === null ? null : poly(raw.silhouette, 'silhouette') ?? null
  const gr = typeof raw.groundRow === 'number' && Number.isFinite(raw.groundRow) ? raw.groundRow * k : null
  const byId = <T extends { id: string }>(a: T[]): T[] => [...a].sort((x, y) => (x.id < y.id ? -1 : 1))
  const sketch = ElevationSketchSchema.parse({
    schema: ELEVATION_SKETCH_SCHEMA,
    schemaVersion: ELEVATION_SKETCH_VERSION,
    sketchId: `sketch-${sha(f.frameId).slice(0, 8)}-${sha(pic.png).slice(0, 12)}`,
    frameId: f.frameId,
    source: { imageSha256: sha(pic.png), width: f.raster.width, height: f.raster.height, scale: k },
    groundRow: gr,
    silhouette,
    roofs: byId(roofs),
    walls: byId(walls),
    openings: byId(openings),
    elements: byId(elements),
    producer: { kind: 'API_CONTOUR_READING', model: turn.model, promptVersion: ELEVATION_SKETCH_PROMPT_VERSION },
    refused,
  })
  return { sketch, raw, usd, ...(turn.requestId ? { requestId: turn.requestId } : {}) }
}

/** The fixed low-poly palette of the sketch (and of the finish classes it carries). */
export const SKETCH_PALETTE = {
  background: [255, 255, 255],
  LIGHT_RENDER: [234, 230, 222],
  DARK_RENDER: [70, 70, 74],
  TIMBER: [176, 122, 74],
  BRICK: [154, 116, 96],
  METAL: [150, 152, 156],
  UNKNOWN: [200, 196, 188],
  roof: [88, 84, 80],
  WINDOW: [150, 196, 222],
  GLAZED_DOOR: [150, 196, 222],
  GLAZED_WALL: [150, 196, 222],
  DOOR: [110, 78, 52],
  GATE: [128, 130, 136],
  element: [60, 60, 64],
  outline: [30, 30, 32],
} as const

/**
 * The sketch drawn at the frame's exact size: walls by class, roof planes, openings, elements, a 1 px dark outline on
 * every contour so a light frame stays distinct from the white background. Deterministic: the same sketch, the same bytes.
 */
export function renderSketch(s: ElevationSketch): Raster {
  const W = s.source.width
  const H = s.source.height
  const data = new Uint8ClampedArray(W * H * 4)
  for (let i = 0; i < W * H; i++) {
    data[4 * i] = 255
    data[4 * i + 1] = 255
    data[4 * i + 2] = 255
    data[4 * i + 3] = 255
  }
  const paint = (poly: ReadonlyArray<readonly [number, number]>, c: readonly number[]): void => {
    const g = grid(W, H)
    fillPolygon(g, poly)
    for (let i = 0; i < W * H; i++) if (g.data[i]) {
      data[4 * i] = c[0]
      data[4 * i + 1] = c[1]
      data[4 * i + 2] = c[2]
    }
  }
  const outline = (poly: ReadonlyArray<readonly [number, number]>): void => {
    for (let i = 0; i < poly.length; i++) {
      const [x0, y0] = poly[i]
      const [x1, y1] = poly[(i + 1) % poly.length]
      const n = Math.max(1, Math.ceil(Math.hypot(x1 - x0, y1 - y0)))
      for (let t = 0; t <= n; t++) {
        const x = Math.round(x0 + ((x1 - x0) * t) / n)
        const y = Math.round(y0 + ((y1 - y0) * t) / n)
        if (x < 0 || y < 0 || x >= W || y >= H) continue
        const k = 4 * (y * W + x)
        data[k] = SKETCH_PALETTE.outline[0]
        data[k + 1] = SKETCH_PALETTE.outline[1]
        data[k + 2] = SKETCH_PALETTE.outline[2]
      }
    }
  }
  // larger walls first, so a zone inside another is drawn over it
  const area = (p: ReadonlyArray<readonly [number, number]>): number => Math.abs(p.reduce((a, q, i) => a + q[0] * p[(i + 1) % p.length][1] - p[(i + 1) % p.length][0] * q[1], 0)) / 2
  for (const w of [...s.walls].sort((a, b) => area(b.polygon) - area(a.polygon) || (a.id < b.id ? -1 : 1))) paint(w.polygon, SKETCH_PALETTE[w.class])
  for (const r of s.roofs) paint(r.polygon, SKETCH_PALETTE.roof)
  for (const e of s.elements) if (e.kind !== 'RAILING' && e.kind !== 'GUTTER_DOWNPIPE') paint(e.polygon, SKETCH_PALETTE.element)
  for (const o of s.openings) paint(o.polygon, SKETCH_PALETTE[o.kind])
  for (const p of [...s.walls.map((w) => w.polygon), ...s.roofs.map((r) => r.polygon), ...s.openings.map((o) => o.polygon), ...s.elements.map((e) => e.polygon)]) outline(p)
  for (const e of s.elements) if (e.kind === 'RAILING') outline(e.polygon)
  return { width: W, height: H, data }
}
export const renderSketchPng = (s: ElevationSketch): Uint8Array => encodePng(renderSketch(s))

export type ProportionExpectation = {
  /** Along this side: which way metres grow across the picture (from the solver's side assignment) and the model's
   * extent of its outer wall faces (from the plans). */
  alongSign: number
  alongMin: number
  alongMax: number
  /** The ridge above ±0.00 (from the section) and the roof's lowest edge as built (the eaves line as drawn). */
  ridge?: number
  eaves?: number
  /** The model's openings on this side, in metres along and up. */
  openings: Array<{ id: string; a0: number; a1: number; b0: number; b1: number }>
  /** The solver's registration of the ORIGINAL elevation, compared for the record only (it may include the eaves). */
  local?: { mpp: number; alongAtPx0: number; zeroRow: number }
}
export type ProportionCheck = {
  verdict: 'ACCEPTED' | 'REJECTED'
  /** The sketch's own registration: one scale for both axes from its wall ends against the plans' extent, ±0.00 from
   * its ridge against the section — what the finish consumer maps it with. */
  projection?: { alongAtPx0: number; alongSign: number; mpp: number; zeroRow: number }
  toleranceM: number
  residuals: Array<{ anchor: string; sketchM: number; expectedM: number; residualM: number; within: boolean }>
  local: Array<{ anchor: string; residualPx: number; residualM: number }>
  openings: Array<{ sketchId: string; modelId?: string; centreResidualM?: number; widthResidualM?: number; status: 'MATCHED' | 'NOT_IN_MODEL' }>
  why: string
}

/**
 * Proportions against metric facts that are not the sketch: one scale from its wall ends against the plans' extent,
 * ±0.00 placed by its ridge against the section; then the anisotropy test — at that one scale its eaves line must land
 * on the model's eaves and its ground line within the terrain window (−0.60…+0.10 m). Tolerance: the sketch's edge
 * uncertainty (3 px of the frame, or twice its downscale, plus one) at that scale, plus 5 cm for the metric facts.
 * A sketch that fails is REJECTED — never stretched to fit (no second scale is fitted). The solver's registration of
 * the original is compared for the record only. Openings are matched at the sketch's own registration; an opening the
 * model lacks is kept and named (it is what a sketch may teach the shape reader).
 */
export function checkProportions(s: ElevationSketch, e: ProportionExpectation): ProportionCheck {
  const tolPx = Math.max(3, 2 * s.source.scale) + 1
  const wallPts = s.walls.flatMap((w) => w.polygon)
  const roofPts = [...(s.silhouette ?? []), ...s.roofs.flatMap((r) => r.polygon)]
  const residuals: ProportionCheck['residuals'] = []
  const local: ProportionCheck['local'] = []
  if (wallPts.length === 0 || roofPts.length === 0 || e.ridge === undefined) return { verdict: 'REJECTED', toleranceM: 0, residuals, local, openings: [], why: wallPts.length === 0 ? 'no wall contour to take a scale from' : roofPts.length === 0 ? 'no roof contour' : 'no ridge from the section to place ±0.00' }
  const left = Math.min(...wallPts.map((p) => p[0]))
  const right = Math.max(...wallPts.map((p) => p[0]))
  const mpp = (e.alongMax - e.alongMin) / Math.max(1, right - left)
  const alongAtPx0 = e.alongSign > 0 ? e.alongMin - mpp * left : e.alongMax + mpp * left
  const ridgeRow = Math.min(...roofPts.map((p) => p[1]))
  const zeroRow = ridgeRow + e.ridge / mpp
  const tolM = tolPx * mpp + 0.05
  const yOf = (row: number): number => (zeroRow - row) * mpp
  const push = (anchor: string, sketchM: number, expectedM: number, within: boolean): void => {
    residuals.push({ anchor, sketchM: Math.round(sketchM * 1000) / 1000, expectedM: Math.round(expectedM * 1000) / 1000, residualM: Math.round((sketchM - expectedM) * 1000) / 1000, within })
  }
  // the eaves are tested only on roof contours (a silhouette's lowest point is the ground, not the eaves)
  if (e.eaves !== undefined && s.roofs.length > 0) {
    const eavesRow = Math.max(...s.roofs.flatMap((r) => r.polygon.map((p) => p[1])))
    const y = yOf(eavesRow)
    push('eaves line at one scale', y, e.eaves, Math.abs(y - e.eaves) <= tolM)
  }
  if (s.groundRow !== null) {
    const y = yOf(s.groundRow)
    push('ground line within the terrain window', y, Math.min(Math.max(y, -0.6), 0.1), y >= -0.6 - tolM && y <= 0.1 + tolM)
  }
  if (e.local) {
    const colOf = (along: number): number => (along - e.local!.alongAtPx0) / (e.alongSign * e.local!.mpp)
    const ends = [colOf(e.alongMin), colOf(e.alongMax)].sort((a, b) => a - b)
    for (const [anchor, px, exp] of [['left wall end', left, ends[0]], ['right wall end', right, ends[1]], ...(s.groundRow !== null ? [['ground row', s.groundRow, e.local.zeroRow]] : [])] as Array<[string, number, number]>) local.push({ anchor, residualPx: Math.round((px - exp) * 10) / 10, residualM: Math.round((px - exp) * e.local.mpp * 1000) / 1000 })
  }
  const openings: ProportionCheck['openings'] = s.openings.map((o) => {
    const xs = o.polygon.map((p) => alongAtPx0 + e.alongSign * mpp * p[0])
    const lo = Math.min(...xs)
    const hi = Math.max(...xs)
    const best = e.openings.map((m) => ({ m, d: Math.abs((m.a0 + m.a1) / 2 - (lo + hi) / 2) })).sort((p, q) => p.d - q.d)[0]
    if (!best || best.d > Math.max(0.6, (hi - lo) / 2)) return { sketchId: o.id, status: 'NOT_IN_MODEL' as const }
    return { sketchId: o.id, modelId: best.m.id, centreResidualM: Math.round(best.d * 1000) / 1000, widthResidualM: Math.round((hi - lo - (best.m.a1 - best.m.a0)) * 1000) / 1000, status: 'MATCHED' as const }
  })
  const bad = residuals.filter((r) => !r.within)
  const ok = bad.length === 0 && residuals.length >= 1
  return {
    verdict: ok ? 'ACCEPTED' : 'REJECTED',
    ...(ok ? { projection: { alongAtPx0, alongSign: e.alongSign, mpp, zeroRow } } : {}),
    toleranceM: Math.round(tolM * 1000) / 1000,
    residuals,
    local,
    openings,
    why: ok ? `one scale ${mpp.toFixed(5)} m/px from the wall ends; ${residuals.map((r) => `${r.anchor} ${r.residualM} m`).join(', ')} within ${tolM.toFixed(3)} m` : residuals.length === 0 ? 'no anchor to test the one scale against' : `at one scale: ${bad.map((b) => `${b.anchor} off by ${b.residualM} m`).join(', ')} (tolerance ${tolM.toFixed(3)} m): not stretched to fit`,
  }
}

/** The sketch's wall zones as an appearance observation of the original elevation (identity map: same frame pixels). */
export function sketchToAppearance(s: ElevationSketch, facade: AppearanceObservation['facade'], sourceByteHash: string): AppearanceObservation {
  return {
    schema: APPEARANCE_OBSERVATION_SCHEMA,
    schemaVersion: APPEARANCE_OBSERVATION_VERSION,
    observationId: `${s.sketchId}-appearance`,
    facade,
    source: { sourceByteHash, imageSha256: s.source.imageSha256, imageWidth: s.source.width, imageHeight: s.source.height, sourceWidth: s.source.width, sourceHeight: s.source.height },
    toSource: [[1, 0, 0], [0, 1, 0]],
    toSourceWhy: 'contours read on the original elevation itself, in its frame pixels (no map)',
    toSourceResidualPx: 0,
    regions: [
      ...s.walls.filter((w) => w.class !== 'UNKNOWN').map((w) => ({ regionId: w.id, class: w.class as AppearanceObservation['regions'][number]['class'], outline: w.polygon, visibility: w.visibility === 'INFERRED' ? ('PARTLY_OCCLUDED' as const) : w.visibility === 'UNKNOWN' ? ('UNCERTAIN' as const) : w.visibility, uncertaintyPx: 3 * s.source.scale })),
      ...s.openings.map((o) => ({ regionId: o.id, class: 'GLASS' as const, outline: o.polygon, visibility: 'VISIBLE' as const, uncertaintyPx: 3 * s.source.scale, hostHint: 'OPENING' as const })),
    ],
    producer: { kind: 'API_CONTOUR_READING', version: SKETCH_RENDERER_VERSION, model: s.producer.model, promptVersion: s.producer.promptVersion },
  }
}
